package com.deardiary.privateapp;
import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import org.json.*;
final class UpdateSheet extends LinearLayout{
 final TextView status;final Button update,later;final ProgressBar progress;private final int ink,muted;private final boolean dark;
 private int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}
 UpdateSheet(Context c,boolean night,JSONObject release,String current,long updatedAt,boolean available,Runnable action,Runnable dismiss){super(c);dark=night;ink=Color.parseColor(dark?"#F3E8ED":"#594553");muted=Color.parseColor(dark?"#C4B1BC":"#8B7781");setOrientation(VERTICAL);setPadding(dp(22),dp(24),dp(22),dp(18));GradientDrawable background=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{Color.parseColor(dark?"#211A27":"#FFF9F6"),Color.parseColor(dark?"#302434":"#F4E8F0")});background.setCornerRadius(dp(28));setBackground(background);
 boolean failed=release.optBoolean("failed");LinearLayout header=new LinearLayout(c);header.setGravity(Gravity.CENTER_VERTICAL);ImageView icon=new ImageView(c);icon.setImageResource(R.drawable.app_icon);header.addView(icon,new LinearLayout.LayoutParams(dp(48),dp(48)));LinearLayout heading=new LinearLayout(c);heading.setOrientation(VERTICAL);heading.setPadding(dp(12),0,0,0);heading.addView(text("DEAR DIARY / UPDATES",10,muted));TextView title=text(failed?"Let's try again":available?"A little refresh":"All up to date",25,ink);title.setTypeface(Typeface.create("serif",Typeface.NORMAL));heading.addView(title);header.addView(heading,new LinearLayout.LayoutParams(-1,-2));addView(header);
 ScrollView scroll=new ScrollView(c);scroll.setFillViewport(false);LinearLayout cards=new LinearLayout(c);cards.setOrientation(VERTICAL);cards.setPadding(0,dp(20),0,dp(8));
 String next=available?"Next version  "+release.optString("version"):failed?"Latest release  Not checked":"Next version  No newer release available";
 cards.addView(card("ON THIS DEVICE\nDear Diary "+current+"\n\n"+next));
 String date=updatedAt>0?java.text.DateFormat.getDateTimeInstance(java.text.DateFormat.MEDIUM,java.text.DateFormat.SHORT).format(new java.util.Date(updatedAt)):"Not available on this device";cards.addView(card("Last installed update\n"+date));
 TextView label=text("What's new",18,ink);label.setPadding(0,dp(8),0,dp(10));cards.addView(label);String notes=release.optString("notes").trim();if(notes.isEmpty())notes=failed?"Connect to the internet, then check again to see the latest release notes.":"Release notes are not available yet. Check again when you are online.";cards.addView(card(notes));
 TextView explain=text(available?"Private release · verified before install\nAndroid will ask you to confirm installation.":failed?"Your installed app has not changed.":"You're on the latest available release.\nA new version will appear here when it's ready.",12,muted);explain.setLineSpacing(dp(4),1);explain.setPadding(0,dp(10),0,dp(8));cards.addView(explain);scroll.addView(cards);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,0,1);sp.bottomMargin=dp(8);addView(scroll,sp);
 progress=new ProgressBar(c,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(100);progress.setProgressTintList(android.content.res.ColorStateList.valueOf(Color.parseColor(dark?"#E6AFC2":"#A97087")));progress.setVisibility(GONE);addView(progress,new LinearLayout.LayoutParams(-1,dp(5)));
 status=text(failed?"Could not check. Try again when connected.":available?"Ready when you are":"Checked just now",12,muted);status.setPadding(0,dp(5),0,dp(12));addView(status);update=new Button(c);update.setText(available?"Update to "+release.optString("version"):"Check again");update.setTextSize(14);update.setAllCaps(false);update.setTextColor(Color.parseColor(dark?"#39212F":"#FFFFFF"));GradientDrawable button=new GradientDrawable();button.setCornerRadius(dp(17));button.setColor(Color.parseColor(dark?"#E6AFC2":"#A97087"));update.setBackground(button);update.setOnClickListener(v->action.run());addView(update,new LinearLayout.LayoutParams(-1,dp(50)));later=new Button(c);later.setAllCaps(false);later.setText(available?"Later":"Close");later.setTextSize(13);later.setTextColor(muted);later.setBackgroundColor(Color.TRANSPARENT);later.setOnClickListener(v->dismiss.run());addView(later,new LinearLayout.LayoutParams(-1,dp(44)));
 }
 private TextView card(String value){TextView t=text(value,13,ink);t.setLineSpacing(dp(5),1);t.setPadding(dp(16),dp(14),dp(16),dp(14));GradientDrawable bg=new GradientDrawable();bg.setCornerRadius(dp(17));bg.setColor(Color.parseColor(dark?"#3A2E3E":"#FFFFFF"));t.setBackground(bg);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(10);t.setLayoutParams(lp);return t;}
 private TextView text(String value,int size,int color){TextView t=new TextView(getContext());t.setText(value);t.setTextSize(size);t.setTextColor(color);return t;}
 void downloading(int percent){progress.setVisibility(VISIBLE);progress.setIndeterminate(false);progress.setProgress(percent);status.setText("Downloading securely · "+percent+"%");update.setText("Downloading...");update.setEnabled(false);}
}
